'use strict';

const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
const pages = new Set(['dashboard', 'tasks', 'calendar', 'meetings', 'errands', 'chat', 'employees', 'locations', 'stores', 'reports']);
const requestedPage = new URLSearchParams(location.search).get('view');
const state = { data: null, page: pages.has(requestedPage) ? requestedPage : 'dashboard', taskFilter: 'all', taskLocation: '', calendarLocation: '', calendarMode: 'month', reportPeriod: 'month', reportUser: '', search: '', calendar: new Date(), storeTab: 'matrix', storeFilters: { agent: '', supervisor: '', district: '', product: '', availability: '' }, conversations: [], activeConversation: '', chatMessages: [], chatHasMore: false, chatBusy: false, chatLoading: false, chatError: '', chatPollBusy: false };
const labels = {
  status: { new: 'Новая', work: 'В работе', wait: 'Ожидает', done: 'Выполнено' },
  priority: { low: 'Низкий', medium: 'Средний', high: 'Высокий', urgent: 'Срочный' },
  eventType: { meeting: 'Встреча', call: 'Звонок', trip: 'Поездка', other: 'Другое' }
};

const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const isoToday = () => localIso(new Date());
const formatDate = value => value ? new Date(`${value}T00:00:00`).toLocaleDateString('ru-RU', { day: 'numeric', month: 'short' }) : '—';
const formatFullDate = value => value ? new Date(`${value}T00:00:00`).toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' }) : '—';
const initials = name => String(name || '').split(/\s+/).slice(0, 2).map(x => x[0]).join('').toUpperCase();
const fileToBase64 = file => new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(new Error('Не удалось прочитать файл'));reader.readAsDataURL(file);});
const isOverdue = item => item.status !== 'done' && item.date < isoToday();
const personName = id => state.data?.users.find(user => user.id === id)?.name || state.data?.employees.find(employee => employee.userId === id)?.name || 'Не назначен';
const locationName = item => item?.locationId ? state.data?.locations.find(location => location.id === item.locationId)?.name || 'Неизвестный объект' : item?.customLocation || item?.place || 'Другое';

async function api(path, options = {}) {
  const response = await fetch(path, { ...options, headers: { 'Content-Type': 'application/json', ...(options.headers || {}) } });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) {
    if (response.status === 401 && !path.includes('/login')) showLogin();
    const error = new Error(payload.error || 'Ошибка запроса'); error.status=response.status; throw error;
  }
  return payload;
}
function toast(message, error = false) {
  const node = $('#toast'); node.textContent = message; node.className = `toast show${error ? ' error' : ''}`;
  clearTimeout(toast.timer); toast.timer = setTimeout(() => node.className = 'toast', 2600);
}
async function refresh(render = true) {
  state.data = await api('/api/bootstrap');
  state.data.stores ||= []; state.data.products ||= []; state.data.matrix ||= {}; state.data.matrixHistory ||= []; state.data.locations ||= [];
  if (render) renderPage();
}
function showLogin() { state.data=null; state.chatPollBusy=false; $('#appView').classList.add('hidden'); $('#loginView').classList.remove('hidden'); $('#loginForm').classList.remove('hidden'); $('#registerForm').classList.add('hidden'); }
function showApp() {
  $('#loginView').classList.add('hidden'); $('#appView').classList.remove('hidden');
  const user = state.data.user;
  if (user.role !== 'director' && state.page === 'reports') {
    state.page = 'dashboard';
    history.replaceState({ page: 'dashboard' }, '', '/');
  }
  $('#sideName').textContent = user.name; $('#sideRole').textContent = user.title;
  $('#sideAvatar').textContent = $('#topAvatar').textContent = initials(user.name);
  $('#reportsNavigation').classList.toggle('hidden', user.role !== 'director');
  $('#navTasksCount').textContent = state.data.tasks.filter(task => task.status !== 'done').length;
  $$('#navigation [data-page]').forEach(item => item.classList.toggle('active', item.dataset.page === state.page));
  renderPage();
}

$('#loginForm').addEventListener('submit', async event => {
  event.preventDefault();
  try {
    await api('/api/auth/login', { method: 'POST', body: JSON.stringify({ userId: $('#loginUser').value, password: $('#loginPassword').value }) });
    await refresh(false); showApp(); loadConversations(true).catch(reportChatError); toast('Вход выполнен');
  } catch (error) { toast(error.message, true); }
});
$('#togglePassword').addEventListener('click', () => { const field = $('#loginPassword'); field.type = field.type === 'password' ? 'text' : 'password'; });
$('#logoutButton').addEventListener('click', async () => { try { await api('/api/auth/logout', { method: 'POST', body: '{}' }); } finally { state.data = null; state.conversations=[]; state.activeConversation=''; state.chatMessages=[]; showLogin(); } });
$('#navigation').addEventListener('click', event => {
  const button = event.target.closest('[data-page]'); if (!button) return;
  const page = button.dataset.page;
  state.page = page; history.pushState({ page }, '', page === 'dashboard' ? '/' : `/?view=${page}`);
  $$('#navigation [data-page]').forEach(item => item.classList.toggle('active', item === button));
  $('#sidebar').classList.remove('open'); renderPage(); if(page==='chat') loadConversations(true).catch(reportChatError);
});
$('#showRegister').addEventListener('click', () => { $('#loginForm').classList.add('hidden'); $('#registerForm').classList.remove('hidden'); });
$('#showLogin').addEventListener('click', () => { $('#registerForm').classList.add('hidden'); $('#loginForm').classList.remove('hidden'); });
$('#registerForm').addEventListener('submit', async event => {
  event.preventDefault(); const body=Object.fromEntries(new FormData(event.target).entries());
  try { await api('/api/auth/register',{method:'POST',body:JSON.stringify(body)}); $('#loginUser').value=body.email; $('#loginPassword').value=body.password; event.target.reset(); $('#showLogin').click(); toast('Компания создана. Теперь войдите в кабинет'); }
  catch(error){ toast(error.message,true); }
});
window.addEventListener('popstate', () => {
  const page = new URLSearchParams(location.search).get('view');
  state.page = pages.has(page) ? page : 'dashboard';
  if (state.data) renderPage();
});
$('#openSidebar').addEventListener('click', () => $('#sidebar').classList.add('open'));
$('#closeSidebar').addEventListener('click', () => $('#sidebar').classList.remove('open'));
$('#quickAdd').addEventListener('click', () => state.page==='stores' ? openStoreModal() : openEntityModal(state.page === 'meetings' || state.page === 'calendar' ? 'event' : state.page === 'errands' ? 'errand' : state.page === 'employees' ? 'employee' : 'task'));
$('#notificationButton').addEventListener('click', () => {
  const notifications=state.data?.notifications||[], overdue=[...(state.data?.tasks||[]),...(state.data?.errands||[])].filter(isOverdue);
  openModal(`<h2>Центр уведомлений</h2><p>Назначения, изменения статусов и контроль сроков.</p><div class="audit-list">${notifications.map(x=>`<div class="audit-row"><i>${x.read?'✓':'!'}</i><div><strong>${esc(x.title)}</strong><span>${esc(x.message)}</span><small>${new Date(x.createdAt).toLocaleString('ru-RU')}</small></div></div>`).join('')}${overdue.map(x=>`<div class="audit-row"><i>!</i><div><strong>${esc(x.title)}</strong><span>Просрочено · ${formatFullDate(x.date)}</span></div></div>`).join('')||empty('Уведомлений нет','Новых событий и нарушений сроков нет')}</div><div class="form-actions"><button class="button secondary" onclick="markNotificationsRead()">Отметить прочитанными</button></div>`);
});
$('#accountButton').addEventListener('click',()=>openModal(`<h2>Настройки аккаунта</h2><p>${esc(state.data.user.email)} · ${esc(state.data.company?.name||'')}</p><form id="passwordForm" class="form-grid"><label class="full">Текущий пароль<input name="currentPassword" type="password" required></label><label>Новый пароль<input name="newPassword" type="password" minlength="8" required></label><label>Повторите пароль<input name="newPasswordConfirm" type="password" minlength="8" required></label><div class="form-actions full"><button type="button" class="button secondary" onclick="closeModal()">Отмена</button><button class="button primary">Изменить пароль</button></div></form>`));
document.addEventListener('submit',async event=>{if(event.target.id!=='passwordForm')return;event.preventDefault();try{await api('/api/auth/change-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target).entries()))});closeModal();toast('Пароль изменён');}catch(error){toast(error.message,true);}});
$('#globalSearch').addEventListener('input', event => { state.search = event.target.value.toLowerCase().trim(); renderPage(); });
document.addEventListener('keydown', event => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); $('#globalSearch').focus(); } if (event.key === 'Escape') closeModal(); });
$('#modal').addEventListener('click', event => { if (event.target.matches('[data-close-modal]')) closeModal(); });

function setHead(title, subtitle, action = '') {
  return `<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="head-actions">${action}</div></div>`;
}
function button(label, entity, extra = '') { return `<button class="button primary" onclick="openEntityModal('${entity}')">＋ ${label}</button>${extra}`; }
function metric(label, value, icon, hint, className = '') { return `<article class="metric"><div class="metric-top"><span>${label}</span><i class="metric-icon">${icon}</i></div><strong class="${className}">${value}</strong><small>${hint}</small></article>`; }
function taskRow(task, compact = true) {
  const status = isOverdue(task) ? 'overdue' : task.status;
  return `<div class="task-row"><button class="check ${task.status === 'done' ? 'done' : ''}" onclick="cycleTask('${task.id}')">${task.status === 'done' ? '✓' : ''}</button><div><h3>${esc(task.title)}</h3><p>${esc(task.category)} · ${esc(locationName(task))} · ${formatDate(task.date)} ${esc(task.time)}</p></div><span class="badge ${status === 'new' ? task.priority : status}">${isOverdue(task) ? 'Просрочено' : labels.status[task.status]}</span>${compact ? '' : `<button class="more" onclick="openEntityModal('task','${task.id}')">•••</button>`}</div>`;
}
function eventRow(event) { return `<div class="event-row"><div class="event-time">${esc(event.time || '—')}<br><small>${formatDate(event.date)}</small></div><div><h3>${esc(event.title)}</h3><p>${esc(locationName(event) || labels.eventType[event.type])}</p></div></div>`; }
function empty(title, text) { return `<div class="empty"><b>${title}</b><span>${text}</span></div>`; }

function renderDashboard() {
  const { tasks, events, errands, presence, user } = state.data;
  const open = tasks.filter(x => x.status !== 'done'); const done = tasks.filter(x => x.status === 'done');
  const overdue = tasks.filter(isOverdue); const completion = tasks.length ? Math.round(done.length / tasks.length * 100) : 0;
  const currentEvents = events.filter(x => x.date >= isoToday()).sort((a, b) => `${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`));
  const greeting = new Date().getHours() < 12 ? 'Доброе утро' : new Date().getHours() < 18 ? 'Добрый день' : 'Добрый вечер';
  $('#pageHost').innerHTML = `${setHead(`${greeting}, ${esc(user.name.split(' ')[0])}`, new Date().toLocaleDateString('ru-RU', { weekday: 'long', day: 'numeric', month: 'long' }), button('Новая задача', 'task'))}
    <div class="metric-grid">${metric('Активные задачи', open.length, '✓', `${tasks.filter(x => x.status === 'work').length} сейчас в работе`)}${metric('Встречи сегодня', events.filter(x => x.date === isoToday()).length, '◫', `${currentEvents.length} предстоящих`)}${metric('Поручения', errands.filter(x => x.status !== 'done').length, '↗', 'Требуют исполнения')}${metric('Просрочено', overdue.length, '!', overdue.length ? 'Обратите внимание' : 'Всё идёт по плану', overdue.length ? 'bad' : '')}</div>
    <div class="content-grid"><section class="panel"><div class="panel-head"><h2>Текущие задачи</h2><button onclick="goPage('tasks')">Все задачи →</button></div>${open.slice().sort((a,b)=>`${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`)).slice(0,6).map(x => taskRow(x)).join('') || empty('Задач нет','Создайте первую задачу')}</section>
    <aside><section class="progress-block"><div class="row"><div><small>Выполнение задач</small><strong>${completion}%</strong></div><small>${done.length} из ${tasks.length}</small></div><div class="progress-track"><i style="width:${completion}%"></i></div></section><section class="panel"><div class="panel-head"><h2>Ближайшие события</h2><button onclick="goPage('calendar')">Календарь →</button></div>${currentEvents.slice(0,4).map(eventRow).join('') || empty('Событий нет','Календарь свободен')}<div class="presence"><i class="dot"></i><div><strong>${user.role === 'assistant' ? 'Мой статус' : 'Статус Амана'}: ${esc(presence.value)}</strong><span>${esc(presence.note || 'Статус обновлён')} · ${new Date(presence.updatedAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</span></div>${user.role === 'assistant' ? `<button class="more" aria-label="Изменить рабочий статус" onclick="openPresenceModal()">•••</button>` : ''}</div></section></aside></div>`;
}

function renderTasks() {
  const filtered = state.data.tasks.filter(item => (state.taskFilter === 'all' || (state.taskFilter === 'over' ? isOverdue(item) : item.status === state.taskFilter)) && (!state.taskLocation || item.locationId === state.taskLocation) && matches(item));
  $('#pageHost').innerHTML = `${setHead('Задачи', 'Планируйте работу, назначайте исполнителей и контролируйте сроки.', button('Новая задача','task'))}<section class="panel"><div class="toolbar"><div class="filter-group">${[['all','Все'],['new','Новые'],['work','В работе'],['wait','Ожидают'],['done','Выполнены'],['over','Просрочены']].map(([id,label])=>`<button class="${state.taskFilter===id?'active':''}" onclick="setTaskFilter('${id}')">${label}</button>`).join('')}</div><select class="toolbar-search" onchange="setTaskLocation(this.value)"><option value="">Все объекты</option>${state.data.locations.filter(x=>x.status==='active').map(x=>option(x.id,x.name,state.taskLocation)).join('')}</select><input class="toolbar-search" placeholder="Поиск задач…" oninput="setLocalSearch(this.value)"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Задача</th><th>Объект</th><th>Срок</th><th>Исполнитель</th><th>Статус</th><th></th></tr></thead><tbody>${filtered.map(task => `<tr><td><strong>${esc(task.title)}</strong><small>${esc(task.description)}</small></td><td>${esc(locationName(task))}</td><td>${formatDate(task.date)} ${esc(task.time)}</td><td>${esc(personName(task.assigneeId))}</td><td><span class="badge ${isOverdue(task)?'overdue':task.status}">${isOverdue(task)?'Просрочено':labels.status[task.status]}</span></td><td><button class="more" onclick="openEntityModal('task','${task.id}')">•••</button></td></tr>`).join('')}</tbody></table>${filtered.length?'':empty('Ничего не найдено','Измените фильтр или создайте задачу')}</div></section>`;
}
function renderCalendar() {
  const view = state.calendar, year = view.getFullYear(), month = view.getMonth(), mode=state.calendarMode;
  const first = mode==='month'?new Date(year,month,1):new Date(view); const offset = mode==='day'?0:(first.getDay()+6)%7; const start = new Date(first); start.setDate(first.getDate()-offset);
  const count=mode==='month'?42:mode==='week'?7:1, weekLabels=mode==='day'?[view.toLocaleDateString('ru-RU',{weekday:'long'})]:['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];
  const cells = [];
  for (let index=0; index<count; index++) {
    const date = new Date(start); date.setDate(start.getDate()+index); const iso = localIso(date);
    const items = [...state.data.events.filter(x=>x.date===iso&&(!state.calendarLocation||x.locationId===state.calendarLocation)).map(x=>({...x,kind:'event'})), ...state.data.tasks.filter(x=>x.date===iso&&(!state.calendarLocation||x.locationId===state.calendarLocation)).map(x=>({...x,kind:'task'})), ...state.data.errands.filter(x=>x.date===iso&&(!state.calendarLocation||x.locationId===state.calendarLocation)).map(x=>({...x,kind:'errand'}))];
    cells.push(`<div class="calendar-day ${mode==='month'&&date.getMonth()!==month?'muted':''} ${iso===isoToday()?'today':''}"><b>${date.getDate()}</b>${items.slice(0,mode==='month'?3:20).map(x=>`<span class="cal-item ${x.kind==='task'?'task':x.kind==='errand'?'errand':''}" title="${esc(x.title)}">${esc(x.time)} ${esc(x.title)}</span>`).join('')}</div>`);
  }
  const upcoming = state.data.events.filter(x=>x.date>=isoToday()&&(!state.calendarLocation||x.locationId===state.calendarLocation)).sort((a,b)=>`${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`)).slice(0,8);
  $('#pageHost').innerHTML = `${setHead('Календарь','Общий график задач, встреч, звонков, поездок и поручений.',button('Событие','event',`<select class="button secondary" onchange="setCalendarLocation(this.value)"><option value="">Все объекты</option>${state.data.locations.filter(x=>x.status==='active').map(x=>option(x.id,x.name,state.calendarLocation)).join('')}</select><div class="filter-group">${[['day','День'],['week','Неделя'],['month','Месяц']].map(([id,label])=>`<button class="${mode===id?'active':''}" onclick="setCalendarMode('${id}')">${label}</button>`).join('')}</div><button class="button secondary" onclick="changeCalendar(-1)">←</button><button class="button secondary" onclick="changeCalendar(1)">→</button>`))}<div class="calendar-shell"><section class="panel calendar-panel"><div class="panel-head" style="padding:20px 20px 0"><h2>${view.toLocaleDateString('ru-RU',{day:mode==='month'?undefined:'numeric',month:'long',year:'numeric'})}</h2><button onclick="calendarToday()">Сегодня</button></div><div class="calendar-week ${mode}">${weekLabels.map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid ${mode}">${cells.join('')}</div></section><aside class="panel"><div class="panel-head"><h2>Ближайшие события</h2></div>${upcoming.map(eventRow).join('')||empty('Событий нет','Добавьте событие')}</aside></div>`;
}
function renderMeetings() {
  const events = state.data.events.filter(matches).sort((a,b)=>`${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`));
  $('#pageHost').innerHTML = `${setHead('Встречи','Переговоры, звонки, совещания и поездки.',button('Новая встреча','event'))}<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Событие</th><th>Тип</th><th>Дата и время</th><th>Место</th><th>Участники</th><th></th></tr></thead><tbody>${events.map(item=>`<tr><td><strong>${esc(item.title)}</strong><small>${esc(item.description)}</small></td><td>${labels.eventType[item.type]}</td><td>${formatFullDate(item.date)} · ${esc(item.time)}</td><td>${esc(locationName(item))}</td><td>${item.participants?.length||0}</td><td><button class="more" onclick="openEntityModal('event','${item.id}')">•••</button></td></tr>`).join('')}</tbody></table>${events.length?'':empty('Встреч нет','Добавьте первую встречу')}</div></section>`;
}
function renderErrands() {
  const items = state.data.errands.filter(matches);
  $('#pageHost').innerHTML = `${setHead('Поручения','Выездные и личные поручения с контролем исполнения.',button('Новое поручение','errand'))}<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Поручение</th><th>Адрес</th><th>Срок</th><th>Исполнитель</th><th>Статус</th><th></th></tr></thead><tbody>${items.map(item=>`<tr><td><strong>${esc(item.title)}</strong><small>${esc(item.description)}</small></td><td>${esc(item.place||'—')}</td><td>${formatDate(item.date)} ${esc(item.time)}</td><td>${esc(personName(item.assigneeId))}</td><td><span class="badge ${isOverdue(item)?'overdue':item.status}">${isOverdue(item)?'Просрочено':labels.status[item.status]}</span></td><td><button class="more" onclick="openEntityModal('errand','${item.id}')">•••</button></td></tr>`).join('')}</tbody></table>${items.length?'':empty('Поручений нет','Создайте первое поручение')}</div></section>`;
}
function renderEmployees() {
  const items = state.data.employees.filter(matches); const canEdit = state.data.user.role==='director';
  $('#pageHost').innerHTML = `${setHead('Сотрудники','Команда, контакты и текущая доступность.',canEdit?button('Добавить сотрудника','employee'):'')}<div class="employee-grid">${items.map(item=>`<article class="employee-card"><div class="employee-card-head"><div class="avatar">${initials(item.name)}</div><div><h3>${esc(item.name)}</h3><p>${esc(item.position)}</p></div>${canEdit?`<button class="more" style="margin-left:auto" aria-label="Редактировать сотрудника" onclick="openEntityModal('employee','${item.id}')">•••</button>`:''}</div><div class="employee-info"><span><i class="status-dot ${item.status==='away'?'away':''}"></i> ${item.status==='away'?'Вне офиса':'Доступен'}</span><span>◉ ${esc(item.department||'Не указан')}</span><span>✆ ${esc(item.phone||'Не указан')}</span><span>✉ ${esc(item.email||'Не указан')}</span></div></article>`).join('')}</div>`;
}
function renderLocations() {
  const canEdit=state.data.user.role==='director', tasks=[...state.data.tasks,...state.data.errands];
  $('#pageHost').innerHTML=`${setHead('Объекты компании','Головной офис, офисы, склады и филиалы.',canEdit?'<button class="button primary" onclick="openLocationModal()">＋ Добавить объект</button>':'')}<div class="location-grid">${state.data.locations.map(location=>{const related=tasks.filter(x=>x.locationId===location.id),overdue=related.filter(isOverdue).length,events=state.data.events.filter(x=>x.locationId===location.id&&x.date>=isoToday()).length,typeLabel={head_office:'Головной офис',office:'Офис',warehouse:'Склад',branch:'Филиал'}[location.type]||'Объект';return `<article class="location-card ${location.status}"><div class="location-card-head"><span>${typeLabel}</span><b>${location.status==='active'?'Активен':'Неактивен'}</b></div><h2>${esc(location.name)}</h2><p>${esc(location.address||'Адрес пока не указан')}</p><dl><div><dt>Ответственный</dt><dd>${esc(location.responsible||'Не указан')}</dd></div><div><dt>Телефон</dt><dd>${esc(location.phone||'Не указан')}</dd></div><div><dt>Задачи</dt><dd>${related.length} · просрочено ${overdue}</dd></div><div><dt>Встречи / выезды</dt><dd>${events}</dd></div></dl><small>${esc(location.note||'Без примечания')}</small>${canEdit?`<button class="button secondary" onclick="openLocationModal('${location.id}')">Редактировать</button>`:''}</article>`}).join('')}</div>`;
}
const matrixLabels = { yes: '✓ Есть', no: '✕ Нет', unchecked: '— Не проверено' };
function matrixValue(storeId, productId) { return state.data.matrix[`${storeId}:${productId}`] || { status: 'unchecked', quantity: 0, comment: '' }; }
function storeMatches(store) {
  const f = state.storeFilters, term = state.search;
  if (f.agent && store.agent !== f.agent || f.supervisor && store.supervisor !== f.supervisor || f.district && store.district !== f.district) return false;
  if (term && ![store.name,store.address,store.agent,store.supervisor,...state.data.products.map(x=>x.name)].some(x=>String(x).toLowerCase().includes(term))) return false;
  if (f.product) { const status=matrixValue(store.id,f.product).status; if (f.availability && status!==f.availability) return false; }
  else if (f.availability && !state.data.products.some(p=>matrixValue(store.id,p.id).status===f.availability)) return false;
  return true;
}
function filterSelect(label, key, values) { return `<label class="matrix-filter">${label}<select onchange="setStoreFilter('${key}',this.value)"><option value="">Все</option>${values.map(x=>option(x,x,state.storeFilters[key])).join('')}</select></label>`; }
function renderStores() {
  const { stores, products, user }=state.data, filtered=stores.filter(storeMatches), f=state.storeFilters;
  const selected=products.find(x=>x.id===f.product), stats=selected?{yes:stores.filter(s=>matrixValue(s.id,selected.id).status==='yes').length,no:stores.filter(s=>matrixValue(s.id,selected.id).status==='no').length,unchecked:stores.filter(s=>matrixValue(s.id,selected.id).status==='unchecked').length}:null;
  const actions=`<button class="button secondary" onclick="openStoreModal()">＋ Добавить торговую точку</button>${user.role==='director'?'<button class="button primary" onclick="openProductModal()">＋ Добавить продукт</button>':''}`;
  const tabs=`<div class="section-tabs"><button class="${state.storeTab==='matrix'?'active':''}" onclick="setStoreTab('matrix')">Матрица продукции</button><button class="${state.storeTab==='list'?'active':''}" onclick="setStoreTab('list')">Список точек</button><button class="${state.storeTab==='products'?'active':''}" onclick="setStoreTab('products')">Продукция</button><button class="${state.storeTab==='history'?'active':''}" onclick="setStoreTab('history')">История</button></div>`;
  const filters=`<div class="matrix-filters">${filterSelect('Агент','agent',[...new Set(stores.map(x=>x.agent).filter(Boolean))])}${filterSelect('Супервайзер','supervisor',[...new Set(stores.map(x=>x.supervisor).filter(Boolean))])}${filterSelect('Район','district',[...new Set(stores.map(x=>x.district).filter(Boolean))])}<label class="matrix-filter">Продукт<select onchange="setStoreFilter('product',this.value)"><option value="">Все</option>${products.map(p=>option(p.id,p.name,f.product)).join('')}</select></label><label class="matrix-filter">Наличие<select onchange="setStoreFilter('availability',this.value)">${option('','Все статусы',f.availability)}${option('no','Только отсутствует',f.availability)}${option('unchecked','Только непроверенные',f.availability)}${option('yes','Есть',f.availability)}</select></label></div>`;
  let content='';
  if(state.storeTab==='list') content=`<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>№</th><th>Название</th><th>Адрес</th><th>Агент</th><th>Супервайзер</th><th>Телефон</th><th>Примечание</th><th></th></tr></thead><tbody>${filtered.map((s,i)=>`<tr><td>${i+1}</td><td><button class="text-link" onclick="openStoreReport('${s.id}')">${esc(s.name)}</button></td><td>${esc(s.address)}</td><td>${esc(s.agent||'—')}</td><td>${esc(s.supervisor||'—')}</td><td>${esc(s.phone||'—')}</td><td>${esc(s.note||'—')}</td><td><button class="more" onclick="openStoreModal('${s.id}')">•••</button></td></tr>`).join('')}</tbody></table></div></section>`;
  else if(state.storeTab==='products') content=`<div class="product-grid">${products.map((p,i)=>`<article class="employee-card"><div class="employee-card-head"><div><h3>${esc(p.name)}</h3><p>${esc(p.category)} · ${esc(p.variant||'Без вида')}</p></div>${user.role==='director'?`<button class="more" onclick="openProductModal('${p.id}')">•••</button>`:''}</div><div class="product-actions">${user.role==='director'&&i?`<button onclick="moveProduct('${p.id}',-1)">← Раньше</button>`:''}${user.role==='director'&&i<products.length-1?`<button onclick="moveProduct('${p.id}',1)">Позже →</button>`:''}</div></article>`).join('')}</div>`;
  else if(state.storeTab==='history') content=`<section class="panel"><div class="audit-list">${state.data.matrixHistory.map(h=>`<div class="audit-row"><i>${matrixLabels[h.newStatus][0]}</i><div><strong>${esc(stores.find(s=>s.id===h.storeId)?.name||'Удалённый магазин')} · ${esc(products.find(p=>p.id===h.productId)?.name||'Удалённый продукт')}</strong><span>${matrixLabels[h.oldStatus]} → ${matrixLabels[h.newStatus]} · ${esc(personName(h.userId))}</span><small>${new Date(h.at).toLocaleString('ru-RU')}</small></div></div>`).join('')||empty('История пуста','Изменения появятся после первой проверки')}</div></section>`;
  else content=`${stats?`<div class="metric-grid matrix-report">${metric('Всего магазинов',stores.length,'▦',selected.name)}${metric('Есть',stats.yes,'✓','Покрытие')}${metric('Нет',stats.no,'✕','Требует задачи')}${metric('Не проверено',stats.unchecked,'—',`Покрытие ${stores.length?Math.round(stats.yes/stores.length*100):0}%`)}</div>`:''}<section class="panel matrix-panel"><div class="panel-head"><h2>Матрица продукции по магазинам</h2><small>${filtered.length} точек · ${products.length} продуктов</small></div><div class="matrix-scroll"><table class="matrix-table"><thead><tr><th class="sticky c1">№</th><th class="sticky c2">Магазин</th><th class="sticky c3">Адрес</th><th class="sticky c4">Агент</th><th class="sticky c5">Супервайзер</th>${products.map(p=>`<th title="${esc(p.category)} · ${esc(p.variant)}">${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${filtered.map((s,i)=>`<tr><td class="sticky c1">${i+1}</td><td class="sticky c2"><button class="text-link" onclick="openStoreReport('${s.id}')">${esc(s.name)}</button></td><td class="sticky c3">${esc(s.address)}</td><td class="sticky c4">${esc(s.agent||'—')}</td><td class="sticky c5">${esc(s.supervisor||'—')}</td>${products.map(p=>{const v=matrixValue(s.id,p.id);return `<td><button class="matrix-status ${v.status}" onclick="openMatrixModal('${s.id}','${p.id}')">${matrixLabels[v.status]}</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="matrix-mobile">${filtered.map(s=>`<article class="store-card"><button class="store-card-title" onclick="openStoreReport('${s.id}')">${esc(s.name)}</button><p>${esc(s.address)}<br>Агент: ${esc(s.agent||'—')} · Супервайзер: ${esc(s.supervisor||'—')}</p>${products.map(p=>{const v=matrixValue(s.id,p.id);return `<button class="mobile-product" onclick="openMatrixModal('${s.id}','${p.id}')"><span>${esc(p.name)}</span><b class="${v.status}">${matrixLabels[v.status]}</b></button>`}).join('')}</article>`).join('')}</div></section>`;
  $('#pageHost').innerHTML=`${setHead('Торговые точки','Контроль представленности продукции по магазинам.',actions)}${tabs}${state.storeTab==='matrix'?filters:''}${content}`;
}
function renderReports() {
  if (state.data.user.role !== 'director') { goPage('dashboard'); return; }
  const now=new Date(),start=new Date(now);if(state.reportPeriod==='today'){}else if(state.reportPeriod==='week')start.setDate(start.getDate()-6);else start.setDate(1);const from=localIso(start);
  const tasks = [...state.data.tasks, ...state.data.errands].filter(item=>item.date>=from&&(!state.reportUser||item.assigneeId===state.reportUser));
  const done = tasks.filter(item => item.status === 'done');
  const active = tasks.filter(item => item.status === 'work');
  const overdue = tasks.filter(isOverdue);
  const completion = tasks.length ? Math.round(done.length / tasks.length * 100) : 0;
  const auditLabels = { create: 'создал(а)', update: 'изменил(а)', delete: 'удалил(а)' };
  const entityLabels = { task: 'задачу', event: 'встречу', errand: 'поручение', employee: 'сотрудника', presence: 'статус' };
  const reportTasks=state.data.tasks.filter(item=>item.date>=from&&(!state.reportUser||item.assigneeId===state.reportUser)),categories = [...new Set(reportTasks.map(item => item.category))];
  const filters=`<div class="toolbar"><label class="matrix-filter">Период<select onchange="setReportPeriod(this.value)">${option('today','Сегодня',state.reportPeriod)}${option('week','Неделя',state.reportPeriod)}${option('month','Месяц',state.reportPeriod)}</select></label><label class="matrix-filter">Сотрудник<select onchange="setReportUser(this.value)"><option value="">Все сотрудники</option>${state.data.users.map(user=>option(user.id,user.name,state.reportUser)).join('')}</select></label></div>`;
  $('#pageHost').innerHTML = `${setHead('Отчёты', 'Контроль исполнения по периоду и сотруднику.')}${filters}
    <div class="metric-grid">${metric('Всего в контроле', tasks.length, '▥', 'Задачи и поручения')}${metric('Выполнено', done.length, '✓', `${completion}% общего объёма`)}${metric('В работе', active.length, '↻', 'Активное исполнение')}${metric('Просрочено', overdue.length, '!', overdue.length ? 'Требует внимания' : 'Нарушений сроков нет')}</div>
    <div class="content-grid"><section class="panel"><div class="panel-head"><h2>Исполнение по направлениям</h2></div><div class="report-bars">${categories.map(category=>{const list=reportTasks.filter(item=>item.category===category);const percent=list.length?Math.round(list.filter(item=>item.status==='done').length/list.length*100):0;return `<div class="report-line"><div><strong>${esc(category)}</strong><span>${list.length} задач · ${percent}% выполнено</span></div><div class="report-track"><i style="width:${percent}%"></i></div></div>`}).join('')||empty('Данных пока нет','Измените период или сотрудника')}</div></section>
    <aside class="panel"><div class="panel-head"><h2>Последние действия</h2></div><div class="audit-list">${state.data.audit.slice(0,12).map(entry=>`<div class="audit-row"><i>${initials(personName(entry.userId))}</i><div><strong>${esc(personName(entry.userId))}</strong><span>${auditLabels[entry.action]||entry.action} ${entityLabels[entry.entity]||entry.entity}</span><small>${new Date(entry.at).toLocaleString('ru-RU')}</small></div></div>`).join('')||empty('Действий пока нет','Изменения появятся здесь')}</div></aside></div>`;
}
async function loadConversations(render = false) {
  if (!state.data) return;
  state.chatLoading = true;
  const previousUnread = state.conversations.reduce((sum,item)=>sum+item.unread,0);
  const payload = await api('/api/chat/conversations');
  state.conversations = Array.isArray(payload) ? payload.filter(item=>item&&item.id&&item.user) : [];
  state.chatError = '';
  const unread = state.conversations.reduce((sum,item)=>sum+item.unread,0), badge=$('#navChatCount'); if(badge) badge.textContent=unread||'';
  if(unread>previousUnread && state.page!=='chat'){const latest=state.conversations.find(item=>item.unread);if(latest)toast(`${latest.user.name}: ${latest.lastMessage?.text?.slice(0,80)||'Новое вложение'}`);}
  state.chatLoading = false;
  if(render && state.page==='chat') safeRenderChat();
}
function reportChatError(error){state.chatLoading=false;if(error?.status===401)return;state.chatError=error?.message||'Не удалось загрузить чат';console.error('Chat:',error);if(state.page==='chat')safeRenderChat();}
function safeRenderChat(){try{renderChat();}catch(error){console.error('Chat render:',error);$('#pageHost').innerHTML=`${setHead('Чат','Безопасное общение внутри ORDO Manager.')}<section class="panel chat-fallback"><h2>Не удалось отобразить чат</h2><p>Остальные разделы продолжают работать.</p><button class="button primary" onclick="retryChat()">Повторить</button></section>`;}}
window.retryChat=()=>{state.chatError='';state.chatLoading=true;safeRenderChat();loadConversations(true).catch(reportChatError);};
async function loadMessages(before='') {
  if(!state.activeConversation||state.chatBusy)return; state.chatBusy=true;
  try{const result=await api(`/api/chat/conversations/${state.activeConversation}/messages?limit=30${before?`&before=${before}`:''}`);state.chatMessages=before?[...result.messages,...state.chatMessages]:result.messages;state.chatHasMore=result.hasMore;await api(`/api/chat/conversations/${state.activeConversation}/read`,{method:'POST',body:'{}'});await loadConversations(false);}finally{state.chatBusy=false;}
}
function renderChat(){
  if(state.chatLoading&&!state.conversations.length){$('#pageHost').innerHTML=`${setHead('Чат','Безопасное общение внутри ORDO Manager.')}<section class="panel chat-fallback"><div class="chat-loader"></div><h2>Загружаем диалоги…</h2></section>`;return;}
  if(state.chatError&&!state.conversations.length){$('#pageHost').innerHTML=`${setHead('Чат','Безопасное общение внутри ORDO Manager.')}<section class="panel chat-fallback"><h2>Чат временно недоступен</h2><p>${esc(state.chatError)}</p><button class="button primary" onclick="retryChat()">Повторить</button></section>`;return;}
  const filtered=state.conversations.filter(item=>!state.search||`${item.user.name} ${item.lastMessage?.text||''}`.toLowerCase().includes(state.search));
  const active=state.conversations.find(item=>item.id===state.activeConversation);
  const dialogs=filtered.map(item=>`<button class="chat-dialog ${item.id===state.activeConversation?'active':''}" onclick="openConversation('${item.id}')"><span class="avatar small">${initials(item.user.name)}</span><span><strong>${esc(item.user.name)}</strong><small>${esc(item.lastMessage?.text||'Начните диалог')}</small></span><time>${item.lastMessage?new Date(item.lastMessage.createdAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):''}</time>${item.unread?`<i>${item.unread}</i>`:''}</button>`).join('')||empty('Диалогов пока нет','Выберите сотрудника');
  const messages=active?state.chatMessages.map(message=>{const mine=message.senderId===state.data.user.id,user=state.data.users.find(x=>x.id===message.senderId);return `<article class="chat-message ${mine?'mine':''}"><div><strong>${esc(user?.name||'Система')}</strong><p>${esc(message.text).replace(/\n/g,'<br>')}</p>${(message.attachments||[]).map(file=>`<a href="/api/attachments/${file.id}" target="_blank" rel="noopener">📎 ${esc(file.name)} · ${Math.ceil(file.size/1024)} КБ</a>`).join('')}<footer>${new Date(message.createdAt).toLocaleString('ru-RU')} · ${mine?(message.readAt?'✓✓ прочитано':'✓ отправлено'):''} <button onclick="createTaskFromMessage('${message.id}')">Создать задачу</button></footer></div></article>`}).join(''):'';
  $('#pageHost').innerHTML=`${setHead('Чат','Безопасное общение внутри ORDO Manager.',`<select class="button secondary" onchange="startConversation(this.value)"><option value="">Новый диалог…</option>${state.data.users.filter(x=>x.id!==state.data.user.id).map(x=>option(x.id,x.name,'')).join('')}</select>`)}<section class="chat-shell ${active?'open':''}"><aside class="chat-dialogs"><input class="chat-search" placeholder="Поиск диалогов…" value="${esc(state.search)}" oninput="setChatSearch(this.value)">${dialogs}</aside><div class="chat-room">${active?`<header><button class="mobile-only icon-button" onclick="closeConversation()">←</button><span class="avatar small">${initials(active.user.name)}</span><div><strong>${esc(active.user.name)}</strong><small>Корпоративный диалог</small></div></header><div id="chatMessages" class="chat-messages" onscroll="chatScroll(this)">${state.chatHasMore?'<button class="load-more" onclick="loadOlderMessages()">Загрузить более ранние</button>':''}${messages}</div><form id="chatForm" class="chat-compose"><textarea name="text" maxlength="8000" rows="1" placeholder="Сообщение…"></textarea><label class="chat-file">📎<input name="attachment" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.docx,.xlsx"></label><button class="button primary">Отправить</button></form>`:empty('Выберите диалог','Переписка откроется здесь')}</div></section>`;
  if(active){const host=$('#chatMessages');host.scrollTop=host.scrollHeight;$('#chatForm').addEventListener('submit',sendChatMessage);$('#chatForm textarea').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.target.form.requestSubmit();}});}
}
window.startConversation=async memberId=>{if(!memberId)return;const result=await api('/api/chat/conversations',{method:'POST',body:JSON.stringify({memberId})});await loadConversations();await openConversation(result.id);};
window.openConversation=async id=>{state.activeConversation=id;state.chatMessages=[];safeRenderChat();try{await loadMessages();safeRenderChat();}catch(error){reportChatError(error);}};
window.closeConversation=()=>{state.activeConversation='';renderChat();}; window.setChatSearch=value=>{state.search=value.toLowerCase().trim();renderChat();};
window.loadOlderMessages=async()=>{if(!state.chatMessages.length)return;const oldHeight=$('#chatMessages').scrollHeight;await loadMessages(state.chatMessages[0].createdAt);renderChat();$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight-oldHeight;};
window.chatScroll=node=>{if(node.scrollTop<30&&state.chatHasMore)loadOlderMessages();};
async function sendChatMessage(event){event.preventDefault();const form=new FormData(event.target),file=form.get('attachment'),body={text:form.get('text')};if(file?.size){if(file.size>4*1024*1024)return toast('Размер файла должен быть не более 4 МБ',true);body.attachment={name:file.name,mime:file.type,data:await fileToBase64(file)};}if(!body.text.trim()&&!body.attachment)return;const button=event.target.querySelector('button');button.disabled=true;try{await api(`/api/chat/conversations/${state.activeConversation}/messages`,{method:'POST',body:JSON.stringify(body)});event.target.reset();await loadMessages();await loadConversations();renderChat();}catch(error){toast(error.message,true);}finally{button.disabled=false;}}
window.createTaskFromMessage=id=>{const message=state.chatMessages.find(x=>x.id===id);if(!message)return;const active=state.conversations.find(x=>x.id===state.activeConversation);openEntityModal('task','',{title:'Задача из чата',description:message.text,assigneeId:active?.user.id||'aman'});};
function renderPage() {
  if (!state.data) return;
  $('#globalSearch').placeholder = state.page === 'stores' ? 'Поиск магазинов, адресов и продукции…' : 'Поиск по задачам и встречам…';
  $('#navTasksCount').textContent = state.data.tasks.filter(task=>task.status!=='done').length;
  ({ dashboard: renderDashboard, tasks: renderTasks, calendar: renderCalendar, meetings: renderMeetings, errands: renderErrands, chat: safeRenderChat, employees: renderEmployees, locations: renderLocations, stores: renderStores, reports: renderReports }[state.page] || renderDashboard)();
}
function matches(item) { if (!state.search) return true; return Object.values(item).some(value => String(value).toLowerCase().includes(state.search)); }
function localIso(date) { const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0'); return `${y}-${m}-${d}`; }
window.goPage = page => { state.page=page; history.pushState({ page }, '', page === 'dashboard' ? '/' : `/?view=${page}`); $$('#navigation [data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page)); renderPage(); };
window.markNotificationsRead=async()=>{await api('/api/notifications/read',{method:'POST',body:'{}'});closeModal();await refresh();toast('Уведомления прочитаны');};
window.setReportPeriod=value=>{state.reportPeriod=value;renderReports();};window.setReportUser=value=>{state.reportUser=value;renderReports();};
window.setTaskFilter = value => { state.taskFilter=value; renderTasks(); };
window.setTaskLocation = value => { state.taskLocation=value; renderTasks(); };
window.setCalendarLocation = value => { state.calendarLocation=value; renderCalendar(); };
window.setLocalSearch = value => { state.search=value.toLowerCase().trim(); renderTasks(); };
window.setCalendarMode=mode=>{state.calendarMode=mode;renderCalendar();};
window.changeCalendar=amount=>{if(state.calendarMode==='month')state.calendar.setMonth(state.calendar.getMonth()+amount);else state.calendar.setDate(state.calendar.getDate()+amount*(state.calendarMode==='week'?7:1));renderCalendar();};
window.calendarToday = () => { state.calendar=new Date(); renderCalendar(); };
window.setStoreTab=value=>{state.storeTab=value;renderStores();};
window.setStoreFilter=(key,value)=>{state.storeFilters[key]=value;renderStores();};
window.openStoreModal=(id='')=>{const s=id?state.data.stores.find(x=>x.id===id):{};openModal(`<h2>${id?'Изменить':'Добавить'} торговую точку</h2><form id="storeForm" class="form-grid"><label class="full">Название<input name="name" required maxlength="160" value="${esc(s.name)}"></label><label class="full">Адрес<input name="address" required value="${esc(s.address)}"></label><label>Район<input name="district" value="${esc(s.district)}"></label><label>Торговый агент<input name="agent" value="${esc(s.agent)}"></label><label>Супервайзер<input name="supervisor" value="${esc(s.supervisor)}"></label><label>Телефон<input name="phone" value="${esc(s.phone)}"></label><label class="full">Примечание<textarea name="note">${esc(s.note)}</textarea></label><div class="form-actions full">${id&&state.data.user.role==='director'?`<button type="button" class="button danger" onclick="deleteStore('${id}')">Удалить</button>`:''}<button type="button" class="button secondary" onclick="closeModal()">Отмена</button><button class="button primary">Сохранить</button></div></form>`);$('#storeForm').addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/stores${id?`/${id}`:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))});closeModal();await refresh();toast('Торговая точка сохранена');}catch(error){toast(error.message,true);}});};
window.deleteStore=async id=>{if(!confirm('Удалить торговую точку и её отметки?'))return;await api(`/api/stores/${id}`,{method:'DELETE'});closeModal();await refresh();};
window.openProductModal=(id='')=>{const p=id?state.data.products.find(x=>x.id===id):{};openModal(`<h2>${id?'Изменить':'Добавить'} продукт</h2><form id="productForm" class="form-grid"><label class="full">Название продукта<input name="name" required maxlength="160" value="${esc(p.name)}"></label><label>Категория<input name="category" value="${esc(p.category)}"></label><label>Вид / вкус<input name="variant" value="${esc(p.variant)}"></label><label class="full">Примечание<textarea name="note">${esc(p.note)}</textarea></label><div class="form-actions full">${id?`<button type="button" class="button danger" onclick="deleteProduct('${id}')">Удалить</button>`:''}<button type="button" class="button secondary" onclick="closeModal()">Отмена</button><button class="button primary">Сохранить</button></div></form>`);$('#productForm').addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/products${id?`/${id}`:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))});closeModal();await refresh();toast('Продукт сохранён');}catch(error){toast(error.message,true);}});};
window.deleteProduct=async id=>{if(!confirm('Удалить продукт и все его отметки?'))return;await api(`/api/products/${id}`,{method:'DELETE'});closeModal();await refresh();};
window.moveProduct=async(id,delta)=>{const ids=state.data.products.map(x=>x.id),index=ids.indexOf(id),target=index+delta;if(target<0||target>=ids.length)return;[ids[index],ids[target]]=[ids[target],ids[index]];await api('/api/products/reorder',{method:'POST',body:JSON.stringify({ids})});await refresh();};
window.openMatrixModal=(storeId,productId)=>{const s=state.data.stores.find(x=>x.id===storeId),p=state.data.products.find(x=>x.id===productId),v=matrixValue(storeId,productId);openModal(`<h2>${esc(s.name)} · ${esc(p.name)}</h2><p>Обновите результат последней проверки.</p><form id="matrixForm" class="form-grid"><label class="full">Наличие<select name="status">${option('yes','✓ Есть',v.status)}${option('no','✕ Нет',v.status)}${option('unchecked','— Не проверено',v.status)}</select></label><label>Количество<input type="number" min="0" name="quantity" value="${v.quantity||0}"></label><label>Кто проверил<input value="${esc(personName(v.checkedBy))}" disabled></label><label class="full">Комментарий<textarea name="comment">${esc(v.comment)}</textarea></label><div class="form-actions full">${v.status==='no'?`<button type="button" class="button secondary" onclick="createMatrixTask('${storeId}','${productId}')">Создать задачу</button>`:''}<button type="button" class="button secondary" onclick="closeModal()">Отмена</button><button class="button primary">Сохранить</button></div></form>`);$('#matrixForm').addEventListener('submit',async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target).entries());body.storeId=storeId;body.productId=productId;try{await api('/api/matrix',{method:'POST',body:JSON.stringify(body)});closeModal();await refresh();toast('Отметка сохранена');}catch(error){toast(error.message,true);}});};
window.createMatrixTask=async(storeId,productId)=>{const s=state.data.stores.find(x=>x.id===storeId),p=state.data.products.find(x=>x.id===productId);await api('/api/tasks',{method:'POST',body:JSON.stringify({title:`Обеспечить наличие: ${p.name}`,description:`Магазин: ${s.name}\nАдрес: ${s.address}`,category:'Торговые точки',date:isoToday(),assigneeId:'aman',priority:'high'})});closeModal();await refresh();toast('Задача создана');};
window.openStoreReport=storeId=>{const s=state.data.stores.find(x=>x.id===storeId);openModal(`<h2>${esc(s.name)}</h2><p>${esc(s.address)} · Агент: ${esc(s.agent||'—')} · Супервайзер: ${esc(s.supervisor||'—')}</p><div class="store-report">${state.data.products.map(p=>{const v=matrixValue(s.id,p.id);return `<button class="mobile-product" onclick="openMatrixModal('${s.id}','${p.id}')"><span>${esc(p.name)}<small>${esc(p.category)} · ${v.quantity||0} шт.</small></span><b class="${v.status}">${matrixLabels[v.status]}</b></button>`}).join('')}</div>`);};
window.cycleTask = async id => { const task=state.data.tasks.find(x=>x.id===id); const order=['new','work','wait','done']; try{await api(`/api/tasks/${id}`,{method:'PATCH',body:JSON.stringify({status:order[(order.indexOf(task.status)+1)%order.length]})});await refresh();}catch(error){toast(error.message,true);} };

function openModal(html) { $('#modalContent').innerHTML=html; $('#modal').classList.remove('hidden'); $('#modal').setAttribute('aria-hidden','false'); }
function closeModal() { $('#modal').classList.add('hidden'); $('#modal').setAttribute('aria-hidden','true'); }
window.closeModal=closeModal;
function option(value,label,current){return `<option value="${value}" ${value===current?'selected':''}>${label}</option>`;}
function assigneeOptions(current){const selected=state.data.users.some(user=>user.id===current)?current:(state.data.user.role==='assistant'?state.data.user.id:(state.data.users.find(user=>user.role==='assistant')?.id||state.data.user.id));return state.data.users.map(user=>option(user.id,user.name,selected)).join('');}
function locationOptions(current, otherLabel='Другое'){return `<option value="">${otherLabel}</option>${state.data.locations.filter(x=>x.status==='active'||x.id===current).map(x=>option(x.id,x.name,current)).join('')}`;}
window.openEntityModal = (type,id='',preset={}) => {
  const configs={task:{collection:'tasks',title:'задачу'},event:{collection:'events',title:'встречу'},errand:{collection:'errands',title:'поручение'},employee:{collection:'employees',title:'сотрудника'}};
  const config=configs[type], item=id?state.data[config.collection].find(x=>x.id===id):preset; const editing=Boolean(id);
  let fields='';
  if(type==='task'||type==='errand') fields=`<label class="full">Название<input name="title" value="${esc(item.title)}" required maxlength="160"></label><label class="full">Описание<textarea name="description">${esc(item.description)}</textarea></label>${type==='task'?`<label>Категория<select name="category">${['Общее','Документы','Офис','Склад','Логистика','Гости'].map(x=>option(x,x,item.category)).join('')}</select></label><label>Место / объект<select name="locationId">${locationOptions(item.locationId)}</select></label><label class="full">Другое место<input name="customLocation" value="${esc(item.customLocation)}"></label>`:`<label>Адрес<input name="place" value="${esc(item.place)}"></label><label>Объект<select name="locationId">${locationOptions(item.locationId)}</select></label>`}<label>Исполнитель<select name="assigneeId">${assigneeOptions(item.assigneeId||'aman')}</select></label><label>Дата<input name="date" type="date" value="${item.date||isoToday()}" required></label><label>Время<input name="time" type="time" value="${item.time||''}"></label><label>Приоритет<select name="priority">${Object.entries(labels.priority).map(([v,l])=>option(v,l,item.priority||'medium')).join('')}</select></label><label>Статус<select name="status">${Object.entries(labels.status).map(([v,l])=>option(v,l,item.status||'new')).join('')}</select></label><label class="full">Комментарий о результате<textarea name="resultComment" maxlength="2000">${esc(item.resultComment)}</textarea></label>`;
  if(type==='event') { const selectedParticipants=editing?(item.participants||[]):state.data.users.map(user=>user.id); fields=`<label class="full">Название<input name="title" value="${esc(item.title)}" required maxlength="160"></label><label class="full">Описание<textarea name="description">${esc(item.description)}</textarea></label><label>Тип<select name="type">${Object.entries(labels.eventType).map(([v,l])=>option(v,l,item.type||'meeting')).join('')}</select></label><label>Объект<select name="locationId">${locationOptions(item.locationId,'Другое место')}</select></label><label>Другое место<input name="place" value="${esc(item.place)}"></label><label>Дата<input name="date" type="date" value="${item.date||isoToday()}" required></label><label>Начало<input name="time" type="time" value="${item.time||''}"></label><label>Окончание<input name="endTime" type="time" value="${item.endTime||''}"></label><label>Участники<select name="participants" multiple>${state.data.users.map(user=>option(user.id,user.name,selectedParticipants.includes(user.id)?user.id:'')).join('')}</select></label>`; }
  if(type==='task'||type==='errand') fields+=`${editing?`<div class="full audit-list">${(item.comments||[]).map(c=>`<div class="audit-row"><i>◦</i><div><strong>${esc(personName(c.userId))}</strong><span>${esc(c.text)}</span><small>${new Date(c.createdAt).toLocaleString('ru-RU')}</small></div></div>`).join('')||'<small>Комментариев пока нет</small>'}</div><div class="full attachment-list">${(item.attachments||[]).map(file=>`<div><a href="/api/attachments/${file.id}" target="_blank" rel="noopener">${esc(file.name)} · ${Math.ceil(file.size/1024)} КБ</a><button type="button" class="more" onclick="deleteAttachment('${file.id}','${type}','${id}')">×</button></div>`).join('')||'<small>Вложений пока нет</small>'}</div><label class="full">Новый комментарий<textarea name="newComment" maxlength="2000"></textarea></label>`:''}<label class="full">Прикрепить файл до 4 МБ<input name="attachment" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.docx,.xlsx"></label>`;
  if(type==='employee') fields=`<label class="full">ФИО<input name="name" value="${esc(item.name)}" required></label><label>Должность<input name="position" value="${esc(item.position)}" required></label><label>Подразделение<input name="department" value="${esc(item.department)}"></label><label>Телефон<input name="phone" value="${esc(item.phone)}"></label><label>Email для входа<input name="email" type="email" value="${esc(item.email)}"></label>${editing?'':`<label>Временный пароль<input name="password" type="password" minlength="8" placeholder="Не менее 8 символов"></label>`}<label>Статус<select name="status">${option('office','В офисе',item.status||'office')}${option('online','На связи',item.status)}${option('away','Вне офиса',item.status)}</select></label>`;
  openModal(`<h2>${editing?'Изменить':'Добавить'} ${config.title}</h2><p>Заполните основные данные и сохраните изменения.</p><form id="entityForm" class="form-grid">${fields}<div class="form-actions full">${editing?`<button type="button" class="button danger" onclick="deleteEntity('${type}','${id}')">Удалить</button>`:''}<button type="button" class="button secondary" onclick="closeModal()">Отмена</button><button class="button primary">Сохранить</button></div></form>`);
  $('#entityForm').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.target);const body=Object.fromEntries(form.entries()),newComment=body.newComment,attachment=form.get('attachment');delete body.newComment;delete body.attachment;if(type==='event')body.participants=form.getAll('participants');try{const saved=await api(`/api/${config.collection}${editing?`/${id}`:''}`,{method:editing?'PATCH':'POST',body:JSON.stringify(body)}),entityId=editing?id:saved.id;if(newComment&&(type==='task'||type==='errand'))await api(`/api/${config.collection}/${entityId}/comments`,{method:'POST',body:JSON.stringify({text:newComment})});if(attachment?.size){if(attachment.size>4*1024*1024)throw new Error('Размер файла должен быть не более 4 МБ');await api(`/api/${config.collection}/${entityId}/attachments`,{method:'POST',body:JSON.stringify({name:attachment.name,mime:attachment.type,data:await fileToBase64(attachment)})});}closeModal();await refresh();toast(editing?'Изменения сохранены':'Запись создана');}catch(error){toast(error.message,true);}});
};
window.deleteEntity=async(type,id)=>{if(!confirm('Удалить запись без возможности восстановления?'))return;const collection={task:'tasks',event:'events',errand:'errands',employee:'employees'}[type];try{await api(`/api/${collection}/${id}`,{method:'DELETE'});closeModal();await refresh();toast('Запись удалена');}catch(error){toast(error.message,true);}};
window.deleteAttachment=async(fileId,type,entityId)=>{if(!confirm('Удалить вложение?'))return;try{await api(`/api/attachments/${fileId}`,{method:'DELETE'});await refresh(false);openEntityModal(type,entityId);toast('Вложение удалено');}catch(error){toast(error.message,true);}};
window.openLocationModal=(id='')=>{const l=id?state.data.locations.find(x=>x.id===id):{};openModal(`<h2>${id?'Изменить':'Добавить'} объект</h2><form id="locationForm" class="form-grid"><label class="full">Название объекта<input name="name" required value="${esc(l.name)}"></label><label>Тип объекта<select name="type">${option('head_office','Головной офис',l.type||'office')}${option('office','Офис',l.type)}${option('warehouse','Склад',l.type)}${option('branch','Филиал',l.type)}</select></label><label>Статус<select name="status">${option('active','Активен',l.status||'active')}${option('inactive','Неактивен',l.status)}</select></label><label class="full">Адрес<input name="address" value="${esc(l.address)}"></label><label>Ответственный<input name="responsible" value="${esc(l.responsible)}"></label><label>Телефон<input name="phone" value="${esc(l.phone)}"></label><label class="full">Примечание<textarea name="note">${esc(l.note)}</textarea></label><div class="form-actions full">${id?`<button type="button" class="button danger" onclick="deleteLocation('${id}')">Удалить</button>`:''}<button type="button" class="button secondary" onclick="closeModal()">Отмена</button><button class="button primary">Сохранить</button></div></form>`);$('#locationForm').addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/locations${id?`/${id}`:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))});closeModal();await refresh();toast('Объект сохранён');}catch(error){toast(error.message,true);}});};
window.deleteLocation=async id=>{if(!confirm('Удалить объект? Связанные записи сохранятся без привязки к нему.'))return;try{await api(`/api/locations/${id}`,{method:'DELETE'});closeModal();await refresh();toast('Объект удалён');}catch(error){toast(error.message,true);}};
window.openPresenceModal=()=>{const p=state.data.presence;openModal(`<h2>Я сейчас</h2><p>Статус виден директору на главном экране.</p><form id="presenceForm" class="form-grid"><label class="full">Текущее место<select name="value">${['В головном офисе','На складе №1','На складе №2','На встрече','В пути','Другое'].map(x=>option(x,x,p.value)).join('')}</select></label><label class="full">Комментарий<input name="note" value="${esc(p.note)}" maxlength="240"></label><div class="form-actions full"><button type="button" class="button secondary" onclick="closeModal()">Отмена</button><button class="button primary">Обновить</button></div></form>`);$('#presenceForm').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/presence',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))});closeModal();await refresh();toast('Статус обновлён');}catch(error){toast(error.message,true);}});};

(async()=>{try{await refresh(false);showApp();loadConversations(true).catch(reportChatError);}catch{showLogin();}})();
setInterval(async()=>{if(!state.data||state.chatPollBusy)return;state.chatPollBusy=true;try{const before=state.chatMessages.at(-1)?.createdAt||0;await loadConversations(false);if(state.page==='chat'&&state.activeConversation){const result=await api(`/api/chat/conversations/${state.activeConversation}/messages?limit=30`),messages=Array.isArray(result.messages)?result.messages:[];if(messages.at(-1)?.createdAt>before){const draft=$('#chatForm textarea')?.value||'';state.chatMessages=messages;await api(`/api/chat/conversations/${state.activeConversation}/read`,{method:'POST',body:'{}'});safeRenderChat();if(draft&&$('#chatForm textarea'))$('#chatForm textarea').value=draft;}}else if(state.page==='chat')safeRenderChat();}catch(error){reportChatError(error);}finally{state.chatPollBusy=false;}},4000);
